// 道具刷光：斜向光带扫过，只作用在实体（alpha）上
uniform sampler2D u_sprite;  // 道具图（带透明通道）
uniform float u_width;       // @range 0.02 0.5 @step 0.01 @default 0.06 @label 光带宽度
uniform float u_angle;       // @range -1 1 @step 0.01 @default -0.42 @label 扫光角度
uniform vec3  u_color;       // @color @label 光颜色
uniform float u_gain;        // @range 0 4 @step 0.01 @default 0.7 @label 亮度
uniform float u_trail;       // @range 0 1 @step 0.01 @default 0.12 @label 余晖

void main() {
  vec4 s = texture(u_sprite, vUv);

  // 沿角度方向做投影，光带在该轴上移动
  float ca = cos(u_angle), sa = sin(u_angle);
  float d = vUv.x * ca + vUv.y * sa;

  // 头尾各留一点余量，保证光带完整扫过
  float head = mix(-0.25, 1.25, sl_easeInOut(u_t01));

  // 主光带 + 更宽的一层余晖（pow 负数底未定义，平方写成 q*q）
  float q = (d - head) / u_width;
  float band = exp(-q * q);
  float qh = (d - head) / (u_width * 2.6);
  float halo = exp(-qh * qh) * u_trail;

  // 只在实体上（alpha 当遮罩），边缘用 alpha 软过渡
  float mask = smoothstep(0.0, 0.85, s.a);
  vec3 shine = u_color * (band + halo) * u_gain * mask;

  vec3 c = s.rgb + shine;
  fragColor = vec4(c, s.a);
}

// 描边：先把 alpha 二值化，再在「形状」上做 Sobel，得到一圈干净的发光线
uniform sampler2D u_sprite;  // 道具图（靠 alpha 找边）
uniform float u_thickness;   // @range 1 6 @step 0.1 @default 2.0 @label 描边粗细
uniform vec3  u_color;       // @color @label 描边颜色
uniform float u_gain;        // @range 0 4 @step 0.01 @default 2.4 @label 亮度
uniform float u_freq;        // @range 0 6 @step 0.05 @default 1.4 @label 呼吸次数
uniform float u_soft;        // @range 0.02 0.5 @step 0.01 @default 0.12 @label 边缘柔化

// 把 alpha 阈值化成形状：直接用原始 alpha（软边）会让 Sobel 输出一条很宽的带子
float shape(vec2 uv) {
  return smoothstep(0.5 - u_soft, 0.5 + u_soft, texture(u_sprite, uv).a);
}

void main() {
  vec2 e = u_texel * u_thickness;

  float l  = shape(vUv - vec2(e.x, 0.0));
  float r  = shape(vUv + vec2(e.x, 0.0));
  float b  = shape(vUv - vec2(0.0, e.y));
  float t  = shape(vUv + vec2(0.0, e.y));
  float tl = shape(vUv - e);
  float tr = shape(vUv + vec2(e.x, -e.y));
  float bl = shape(vUv + vec2(-e.x, e.y));
  float br = shape(vUv + e);

  // Sobel：形状的梯度就是轮廓
  float gx = (tl + 2.0 * l + bl) - (tr + 2.0 * r + br);
  float gy = (tl + 2.0 * t + tr) - (bl + 2.0 * b + br);
  float edge = clamp(sqrt(gx * gx + gy * gy), 0.0, 1.0);

  // 呼吸：亮度做正弦起伏
  float breath = 0.45 + 0.55 * (0.5 + 0.5 * sin(u_time * u_freq * TAU));

  vec3 col = u_color * edge * breath;

  // 颜色保持色相，亮度交给 alpha，叠在背景上不会糊成一片白
  float m = max(col.r, max(col.g, col.b));
  fragColor = vec4(col / max(m, 1e-3), clamp(m * u_gain, 0.0, 1.0));
}

// 柔光：对上一 Pass 做一次 9 tap 高斯，用来把描边晕开
uniform sampler2D u_src;   // 上一 Pass 的输出
uniform float u_radius;    // @range 0.5 8 @step 0.1 @default 2.4 @label 扩散半径
uniform float u_gain;      // @range 0 3 @step 0.01 @default 1.1 @label 增益

void main() {
  vec2 e = u_texel * u_radius;
  vec4 sum = texture(u_src, vUv) * 0.227;
  sum += (texture(u_src, vUv + vec2(e.x, 0.0)) + texture(u_src, vUv - vec2(e.x, 0.0))) * 0.158;
  sum += (texture(u_src, vUv + vec2(0.0, e.y)) + texture(u_src, vUv - vec2(0.0, e.y))) * 0.158;
  sum += (texture(u_src, vUv + e) + texture(u_src, vUv - e)) * 0.05;
  sum += (texture(u_src, vUv + vec2(e.x, -e.y)) + texture(u_src, vUv + vec2(-e.x, e.y))) * 0.05;

  // 保留原图一部分，避免糊成一团
  vec4 base = texture(u_src, vUv);
  vec4 outCol = mix(base, sum, 0.75) * u_gain;
  fragColor = vec4(outCol.rgb, clamp(outCol.a, 0.0, 1.0));
}

// 刀光 · 弧形横扫
// 一次性效果：u_t01 从 0 走到 1，刀光沿弧线从左上扫到右下。
uniform float u_intensity; // @range 0 3 @step 0.01 @default 1.6 @label 强度
uniform float u_spread;    // @range 0.5 3 @step 0.01 @default 1.0 @label 拖尾长度
uniform vec3  u_color;     // @color @label 刀光颜色

void main() {
  vec2 p = (vUv - 0.5) * 2.0;
  float r = length(p);
  float ang = atan(p.y, p.x);

  // 扫过角度：-2.4 → 2.4；起手快、收尾慢
  float t = sl_easeOut(u_t01);
  float head = mix(-2.4, 2.4, t);

  // 头部亮线 + 身后拖尾（角度差越大越暗）
  float da = head - ang;
  float lead = exp(-abs(da) * 26.0);
  float trail = exp(-max(da, 0.0) * 2.0 / u_spread);

  // 弧带：半径 0.62 附近的一条带子
  // 注意：pow(x, 2.0) 在 x<0 时 GLSL 未定义，平方一律写成 q*q
  float q = (r - 0.62) / 0.04;
  float band = exp(-q * q);

  // 只画「已经扫过」的角度范围，起点留一段软过渡
  float swept = smoothstep(-3.15, -2.65, ang) * smoothstep(head + 0.02, head - 0.08, ang);

  float glow = band * swept * (trail * 0.45 + lead * 1.35);

  // 起手时中心的一点光：只在 t01 的开头出现，且随距离快速衰减
  float startFlash = exp(-r * 9.0) * smoothstep(0.3, 0.0, u_t01) * 0.8;

  vec3 col = u_color * (glow + startFlash);

  // 颜色保持色相，亮度交给 alpha：叠在背景上不会因为过曝糊成一片白
  float m = max(col.r, max(col.g, col.b));
  fragColor = vec4(col / max(m, 1e-3), clamp(m * u_intensity, 0.0, 1.0));
}

// 生成一张「任务完成」风格的 UI 面板：暗底 + 金线 + 假文字（透明背景）
// 中间态 Pass：不读输入，只往自己的缓冲里画，供「碎裂」Pass 采样
uniform float u_w;     // @range 0.3 0.95 @step 0.01 @default 0.62 @label 面板宽度
uniform float u_h;     // @range 0.10 0.50 @step 0.01 @default 0.24 @label 面板高度
uniform vec3  u_line;  // @color @default 1 0.82 0.5 @label 金线
uniform vec3  u_fill;  // @color @default 0.05 0.045 0.04 @label 底板

float box(vec2 p, vec2 c, vec2 h, float aa) {
  vec2 d = abs(p - c) - h;
  return 1.0 - smoothstep(-aa, aa, max(d.x, d.y));
}

float sdRound(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
}

void main() {
  float aspect = u_resolution.x / u_resolution.y;
  vec2 p = (vUv - 0.5) * vec2(aspect, 1.0);
  vec2 b = vec2(u_w * aspect * 0.5, u_h * 0.5);
  float aa = 1.4 / u_resolution.y;
  float r = min(0.02, b.y * 0.25);

  // 底板：中间实、上下柔一点，像一块压在画面上的横幅
  float plate = 1.0 - smoothstep(-aa, aa, sdRound(p, b, r));
  float vgrad = 1.0 - pow(abs(p.y) / max(1e-4, b.y), 2.0) * 0.55;
  vec3 col = u_fill;
  float alpha = plate * 0.82 * vgrad;

  // 描边细线
  float border = 1.0 - smoothstep(-aa, aa, abs(sdRound(p, b, r)) - 0.0012);
  col = mix(col, u_line, border * 0.5);
  alpha = max(alpha, border * 0.5);

  // 上下两条金线
  float halfLen = b.x * 0.86;
  float lw = 0.0014;
  float topLine = box(p, vec2(0.0, b.y * 0.62), vec2(halfLen, lw), aa);
  float botLine = box(p, vec2(0.0, -b.y * 0.66), vec2(halfLen, lw), aa);
  float rules = max(topLine, botLine);
  col = mix(col, u_line, rules);
  alpha = max(alpha, rules * 0.92);

  // 金线两端的小菱形
  vec2 dp = vec2(halfLen + 0.013, b.y * 0.62);
  float dia = 1.0 - smoothstep(-aa, aa, abs(p.x - dp.x) + abs(p.y - dp.y) - 0.011);
  float dia2 = 1.0 - smoothstep(-aa, aa, abs(p.x + dp.x) + abs(p.y - dp.y) - 0.011);
  float dias = max(dia, dia2);
  col = mix(col, u_line, dias);
  alpha = max(alpha, dias * 0.95);

  // 标题：一排粗细不一的方块，远看像字
  float tw[6] = float[6](0.052, 0.034, 0.046, 0.030, 0.050, 0.038);
  float gap = 0.012;
  float total = gap * 5.0;
  for (int i = 0; i < 6; i++) total += tw[i];
  float x = -total * 0.5;
  float title = 0.0;
  for (int i = 0; i < 6; i++) {
    title = max(title, box(p, vec2(x + tw[i] * 0.5, 0.014), vec2(tw[i] * 0.5, 0.015), aa));
    x += tw[i] + gap;
  }

  // 副标题：更短更细
  float sw[4] = float[4](0.058, 0.042, 0.050, 0.034);
  float stotal = gap * 3.0;
  for (int i = 0; i < 4; i++) stotal += sw[i];
  float x2 = -stotal * 0.5;
  float sub = 0.0;
  for (int i = 0; i < 4; i++) {
    sub = max(sub, box(p, vec2(x2 + sw[i] * 0.5, -0.050), vec2(sw[i] * 0.5, 0.0075), aa));
    x2 += sw[i] + gap;
  }

  float text = max(title, sub * 0.72);
  col = mix(col, u_line, text);
  alpha = max(alpha, text * 0.95);

  fragColor = vec4(col, clamp(alpha, 0.0, 1.0));
}

// 把输入画面切成碎片：每块各自翻转、缩小、被风带向四周并下坠，边缘亮一圈暖光后消散
// 输入 u_ui 来自「面板」中间态 Pass（显式「指定 Pass」绑定）
// 碎片用抖动网格做 Voronoi 切分，比规则网格更像「碎瓦 / 碎纸」
uniform sampler2D u_ui;
uniform float u_cells;   // @range 6 44 @step 1 @default 22 @label 碎片密度
uniform float u_spread;  // @range 0.05 1.2 @step 0.01 @default 0.38 @label 飘散距离
uniform float u_spin;    // @range 0 3 @step 0.01 @default 1.1 @label 翻转幅度
uniform float u_stagger; // @range 0 0.85 @step 0.01 @default 0.42 @label 错落
uniform float u_fade;    // @range 0.1 1 @step 0.01 @default 0.55 @label 消散
uniform vec3  u_edge;    // @color @default 1 0.78 0.42 @label 边缘光

float h11(float n) { return fract(sin(n * 127.1) * 43758.5453); }
vec2 h21(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

void main() {
  float aspect = u_resolution.x / u_resolution.y;
  vec2 uv = vUv;
  vec2 gp = vec2(uv.x * aspect, uv.y) * u_cells;
  vec2 ip = floor(gp);
  vec2 fp = gp - ip;

  // 抖动网格：找最近的种子（F1）与次近（F2），F2-F1 决定块的边界
  float f1 = 8.0, f2 = 8.0;
  vec2 seed = vec2(0.0);
  vec2 cellId = ip;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 o = vec2(float(x), float(y));
      vec2 id = ip + o;
      vec2 s = o + h21(id + 3.7) * 0.86 + 0.07;
      float d = length(fp - s);
      if (d < f1) { f2 = f1; f1 = d; seed = s; cellId = id; }
      else if (d < f2) { f2 = d; }
    }
  }

  vec2 local = fp - seed;                 // 相对种子，约 [-0.6, 0.6]
  vec2 rnd = h21(cellId + 11.3);

  // 每块自己的进度：错落 + 先慢后快（先翘起、再被风卷走）
  float t = clamp((u_t01 - rnd.x * u_stagger) / max(1e-3, 1.0 - u_stagger), 0.0, 1.0);
  float e = t * t;

  // 往四周飞 + 下坠 + 横向随机，像被风吹散
  vec2 dir = normalize((uv - 0.5) * vec2(aspect, 1.0) + 1e-5);
  vec2 drift = normalize(dir + vec2((rnd.x - 0.5) * 1.1, 0.08)) * (0.5 + rnd.y * 0.7);
  drift.y -= 0.42;
  vec2 off = drift * e * u_spread;

  // 翻转 + 缩小，块与块之间露出缝才有「碎」的感觉
  float ang = (rnd.y - 0.5) * 6.2831 * u_spin * e;
  float ca = cos(ang), sa = sin(ang);
  vec2 pf = mat2(ca, -sa, sa, ca) * local;
  pf *= 1.0 + e * (0.55 + rnd.y * 0.9);
  pf.y += pf.x * 0.22 * e;                // 轻微剪切，更像纸片

  // 回到 uv 空间：从种子中心出发
  vec2 seedUv = vec2((cellId.x + seed.x) / (u_cells * aspect), (cellId.y + seed.y) / u_cells);
  vec2 suv = seedUv + vec2(pf.x / (u_cells * aspect), pf.y / u_cells) - off;

  vec4 src = texture(u_ui, suv);

  // 起飞前不切；起飞后按 Voronoi 边界留缝
  float split = smoothstep(0.0, 0.13, t);
  float edgeDist = f2 - f1;               // 0 在边界，越大越靠块心
  float cellMask = mix(1.0, smoothstep(0.02, 0.10, edgeDist), split);

  float flash = smoothstep(0.0, 0.07, t) * (1.0 - smoothstep(0.07, 0.38, t));
  float vanish = 1.0 - smoothstep(1.0 - u_fade, 1.0, t);
  float alpha = src.a * cellMask * vanish;

  // 迎光的那条边亮一点（用块内到边界的距离取窄带，避免整块描边）
  float rim = smoothstep(0.16, 0.0, edgeDist) * split;
  vec3 col = src.rgb;
  col += u_edge * rim * (0.14 + 0.34 * (1.0 - t));
  // 飞起来之后碎片整体被「照亮」一点，暗底板也能看清形状
  col += u_edge * e * 0.16 * src.a;
  col += u_edge * flash * 0.28 * src.a;
  col *= mix(0.72, 1.0, vanish);

  // 身后留一点余晖，制造速度感
  vec4 trail = texture(u_ui, suv + off * 0.34);
  col += u_edge * trail.a * (1.0 - vanish) * 0.08;

  col = col / max(1.0, dot(col, vec3(0.299, 0.587, 0.114)));  // 高光不过曝
  fragColor = vec4(col, clamp(alpha, 0.0, 1.0));
}

// 水流扰动：噪声推 UV + 高光
uniform sampler2D u_tex;   // 场景（会被扭曲的那张图）
uniform sampler2D u_noise; // 噪声图
uniform float u_strength;  // @range 0 0.12 @step 0.001 @default 0.028 @label 扰动强度
uniform float u_speed;     // @range 0 3 @step 0.01 @default 0.45 @label 流速
uniform float u_scale;     // @range 0.5 8 @step 0.1 @default 2.2 @label 波纹密度
uniform float u_caustic;   // @range 0 3 @step 0.01 @default 0.9 @label 水面高光

void main() {
  vec2 uv = vUv;
  float t = u_time * u_speed;

  // 两层不同速度、不同尺度的噪声滚过去，避免看出平铺
  float n1 = texture(u_noise, uv * u_scale + vec2(t * 0.07, t * 0.03)).r;
  float n2 = texture(u_noise, uv * u_scale * 1.7 - vec2(t * 0.05, t * 0.09)).r;
  vec2 off = vec2(n1, n2) - 0.5;

  // 用噪声当位移场；采样点稍微偏一点就能看出水的折射感
  vec3 c = texture(u_tex, uv + off * u_strength).rgb;

  // 高光：两个噪声相乘取亮部，模拟水面被照亮的地方
  float caustic = pow(clamp(n1 * n2 * 1.9, 0.0, 1.0), 3.0) * u_caustic;
  c += vec3(0.45, 0.7, 1.0) * caustic * 0.5;

  // 极轻的暗角，让画面聚焦
  float vig = 1.0 - 0.25 * pow(length(vUv - 0.5) * 1.8, 2.0);
  fragColor = vec4(c * vig, 1.0);
}
